package org.joda.time;

import java.io.*;
import java.io.IOException;
import java.io.ObjectInputStream;
import java.io.ObjectOutputStream;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import java.util.Locale;
import org.joda.convert.FromString;
import org.joda.convert.ToString;
import org.joda.time.DurationFieldType;
import org.joda.time.Seconds;
import org.joda.time.Weeks;
import org.joda.time.Years;
import org.joda.time.base.BaseDateTime;
import org.joda.time.chrono.ISOChronology;
import org.joda.time.field.AbstractReadableInstantFieldProperty;
import org.joda.time.field.FieldUtils;
import org.joda.time.format.DateTimeFormatter;
import org.joda.time.format.ISODateTimeFormat;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class MutableDateTime_add_TriageGen2Test {

    @Test
    public void testAdd_WithPositiveAmount() {
        // Arrange
        // 2023-01-01 00:00:00.000
        MutableDateTime dt = new MutableDateTime(1672531200000L);
        DurationFieldType type = Years.years();
        int amount = 2;

        // Act
        dt.add(type, amount);

        // Assert: Should be 2025-01-01 00:00:00.000
        assertEquals(1735689600000L, dt.getMillis());
    }

    @Test
    public void testAdd_WithNegativeAmount() {
        // Arrange
        // 2023-01-01 00:00:00.000
        MutableDateTime dt = new MutableDateTime(1672531200000L);
        DurationFieldType type = Years.years();
        int amount = -1;

        // Act
        dt.add(type, amount);

        // Assert: Should be 2022-01-01 00:00:00.000
        assertEquals(1640995200000L, dt.getMillis());
    }

    @Test
    public void testAdd_WithZeroAmount() {
        // Arrange
        long originalMillis = 1672531200000L;
        MutableDateTime dt = new MutableDateTime(originalMillis);
        DurationFieldType type = Seconds.seconds();
        int amount = 0;

        // Act
        dt.add(type, amount);

        // Assert: Nothing should change
        assertEquals(originalMillis, dt.getMillis());
    }

    @Test
    public void testAdd_WithSeconds() {
        // Arrange
        MutableDateTime dt = new MutableDateTime(0); // 1970-01-01 00:00:00.000
        DurationFieldType type = Seconds.seconds();
        int amount = 60;

        // Act
        dt.add(type, amount);

        // Assert: Should be 1970-01-01 00:01:00.000
        assertEquals(60000L, dt.getMillis());
    }

    @Test
    public void testAdd_WithWeeks() {
        // Arrange
        MutableDateTime dt = new MutableDateTime(1672531200000L);
        DurationFieldType type = Weeks.weeks();
        int amount = 1;

        // Act
        dt.add(type, amount);

        // Assert: 2023-01-01 + 7 days = 2023-01-08
        assertEquals(1673136000000L, dt.getMillis());
    }
}
